"""Tool response helpers."""

from __future__ import annotations

import base64
import json
from dataclasses import dataclass, field
from typing import Any

from mcp.types import CallToolResult, ImageContent, TextContent


def json_text(payload: dict[str, Any]) -> str:
    """Serialize a payload in a stable, agent-friendly format."""

    return json.dumps(payload, ensure_ascii=False, sort_keys=True)


@dataclass(frozen=True)
class ImageArtifact:
    """Binary image content returned by a tool."""

    camera: str
    data: bytes
    mime_type: str


@dataclass(frozen=True)
class ToolResponse:
    """Normalized response before converting to MCP content blocks."""

    payload: dict[str, Any]
    images: list[ImageArtifact] = field(default_factory=list)
    text: str | None = None
    is_error: bool = False


def to_call_tool_result(response: ToolResponse) -> CallToolResult:
    """Convert a normalized response into an MCP CallToolResult."""

    content: list[TextContent | ImageContent] = []
    if response.text is not None:
        content.append(TextContent(type="text", text=response.text))
    elif not response.images:
        content.append(TextContent(type="text", text=json_text(response.payload)))

    for image in response.images:
        content.append(
            ImageContent(
                type="image",
                data=base64.b64encode(image.data).decode("ascii"),
                mimeType=image.mime_type,
            )
        )

    return CallToolResult(
        content=content,
        structuredContent=response.payload,
        isError=response.is_error,
    )

from __future__ import annotations

from dataclasses import dataclass
from typing import Any, Callable, Literal, TypeVar


McpResultMode = Literal[
    "action",
    "image_sequence",
    "observation",
    "pose",
    "reachability",
    "reset",
    "status",
]
_MCP_TOOL_METADATA_ATTR = "__galbot_mcp_tool__"

F = TypeVar("F", bound=Callable[..., Any])


@dataclass(frozen=True)
class McpToolMetadata:
    name: str
    description: str
    dangerous: bool = False
    result_mode: McpResultMode = "status"


@dataclass(frozen=True)
class McpToolBinding:
    method_name: str
    function: Callable[..., Any]
    metadata: McpToolMetadata

    @property
    def tool_name(self) -> str:
        return self.metadata.name


def mcp_tool(
    *,
    description: str,
    name: str | None = None,
    dangerous: bool = False,
    result_mode: McpResultMode = "status",
) -> Callable[[F], F]:
    """Attach MCP registration metadata to a public interface method."""

    def decorator(func: F) -> F:
        metadata = McpToolMetadata(
            name=name or func.__name__,
            description=description,
            dangerous=dangerous,
            result_mode=result_mode,
        )
        setattr(func, _MCP_TOOL_METADATA_ATTR, metadata)
        return func

    return decorator


def get_mcp_tool_metadata(obj: Any) -> McpToolMetadata | None:
    return getattr(obj, _MCP_TOOL_METADATA_ATTR, None)


def iter_mcp_tool_bindings(interface_cls: type[Any]) -> tuple[McpToolBinding, ...]:
    bindings: list[McpToolBinding] = []
    for method_name, value in interface_cls.__dict__.items():
        metadata = get_mcp_tool_metadata(value)
        if metadata is None:
            continue
        bindings.append(
            McpToolBinding(
                method_name=method_name,
                function=value,
                metadata=metadata,
            )
        )
    return tuple(bindings)

