        return to_call_tool_result(runtime.call_tool(spec, **bound.arguments))

    annotations = {
        parameter.name: parameter.annotation
        for parameter in spec.signature.parameters.values()
        if parameter.annotation is not inspect.Signature.empty
    }
    annotations["return"] = CallToolResult

    tool.__name__ = spec.name
    tool.__qualname__ = spec.name
    tool.__doc__ = spec.description
    tool.__signature__ = spec.signature
    tool.__annotations__ = annotations
    return tool


def register_tool_specs(
    mcp: FastMCP,
    runtime: GalbotRuntime,
    specs: Sequence[ToolSpec],
) -> None:
    validate_tool_specs(specs)
    for spec in specs:
        mcp.add_tool(
            _make_tool(runtime, spec),
            name=spec.name,
            description=spec.description,
            structured_output=False,
        )


